// catalog_search.cpp: the Ctrl+F item finder's input side. See the header.
#include "catalog_search.h"

#include <atomic>
#include <algorithm>
#include <array>
#include <cctype>
#include <cstdio>
#include <vector>

#include <rex/kernel/xam/avatar_search.h>
#include "kernel/xam/marketplace.h"
#include <rex/logging.h>
#include <rex/ui/virtual_key.h>

#include "search_state.h"
#include "filter_controls.h"

namespace ae_search {

namespace {
// Above the ImGui drawer and the input drivers, which register low.
constexpr size_t kTopmost = ~size_t(0);
constexpr size_t kMaxQuery = 96;
std::atomic<int> g_store_page{0};
std::atomic<bool> g_games_reload{false};
enum class FilterField { kType, kGame, kCategory, kColor, kSort };
constexpr std::array<const char*, 5> kFilterNames{
    "Type", "Source game", "Category", "Color", "Sort"};
struct FilterMenuState {
  bool open = false, picker = false;
  size_t field = 0, choice = 0;
  std::string query;
  std::vector<rex::kernel::xam::AvatarFilterChoice> values;
};
FilterMenuState g_filter;
bool g_filter_y_held = false;

bool ContainsNoCase(const std::string& value, const std::string& query) {
  return std::search(value.begin(), value.end(), query.begin(), query.end(),
      [](char a, char b) { return std::tolower(uint8_t(a)) == std::tolower(uint8_t(b)); }) != value.end();
}

std::vector<rex::kernel::xam::AvatarFilterChoice> VisibleFilterChoices() {
  std::vector<rex::kernel::xam::AvatarFilterChoice> out;
  for (const auto& value : g_filter.values)
    if (ContainsNoCase(value.label, g_filter.query)) out.push_back(value);
  return out;
}

void LoadFilterChoices() {
  using rex::kernel::xam::AvatarFilterChoice;
  using rex::kernel::xam::AvatarFilterDimension;
  switch (FilterField(g_filter.field)) {
    case FilterField::kType: g_filter.values = rex::kernel::xam::QueryAvatarFilterChoices(AvatarFilterDimension::kType); break;
    case FilterField::kGame: g_filter.values = rex::kernel::xam::QueryAvatarFilterChoices(AvatarFilterDimension::kSourceGame); break;
    case FilterField::kCategory: g_filter.values = rex::kernel::xam::QueryAvatarFilterChoices(AvatarFilterDimension::kCategory); break;
    case FilterField::kColor: g_filter.values = rex::kernel::xam::QueryAvatarFilterChoices(AvatarFilterDimension::kColor); break;
    case FilterField::kSort:
      g_filter.values = {{"Name", 0}, {"Type", 0}, {"Source game", 0},
                         {"Category", 0}, {"Color", 0}};
      break;
  }
  g_filter.choice = 0;
  g_filter.query.clear();
}

void PushFilterMenu() {
  Get().SetFilterTextInput(g_filter.open && g_filter.picker);
  if (!g_filter.open) { SetFilterMenuOverlay(false, "", "", ""); return; }
  const size_t before = (g_filter.field + kFilterNames.size() - 1) % kFilterNames.size();
  const size_t after = (g_filter.field + 1) % kFilterNames.size();
  char row[128];
  std::snprintf(row, sizeof(row), "< %s   [%s]   %s >", kFilterNames[before],
                kFilterNames[g_filter.field], kFilterNames[after]);
  std::string selected;
  if (g_filter.picker) {
    const auto visible = VisibleFilterChoices();
    if (!visible.empty()) {
      g_filter.choice = std::min(g_filter.choice, visible.size() - 1);
      char text[160];
      std::snprintf(text, sizeof(text), "%s (%u)", visible[g_filter.choice].label.c_str(), visible[g_filter.choice].count);
      selected = text;
    } else selected = "No owned matches";
  } else selected = "A: choose   X: clear   B/Y: close";
  SetFilterMenuOverlay(true, row, g_filter.query.c_str(), selected.c_str());
}

void ApplyFilterChoice() {
  const auto visible = VisibleFilterChoices();
  if (visible.empty()) return;
  g_filter.choice = std::min(g_filter.choice, visible.size() - 1);
  auto state = rex::kernel::xam::GetAvatarCatalogFilter();
  const auto& label = visible[g_filter.choice].label;
  using rex::kernel::xam::AvatarSortMode;
  switch (FilterField(g_filter.field)) {
    case FilterField::kType: state.type = label; break;
    case FilterField::kGame: state.source_game = label; break;
    case FilterField::kCategory: state.category = label; break;
    case FilterField::kColor: state.color = label; break;
    case FilterField::kSort: {
      const int mode = av2::closet_filter::SortModeFromLabel(label);
      if (mode < 0) return;
      state.sort = AvatarSortMode(mode);
      break;
    }
  }
  rex::kernel::xam::SetAvatarCatalogFilter(state);
  RequestCatalogRebuild();
}
}  // namespace

void SetStorePage(StorePage page) { g_store_page.store(int(page), std::memory_order_relaxed); }
StorePage CurrentStorePage() { return StorePage(g_store_page.load(std::memory_order_relaxed)); }
bool ConsumeGamesReloadRequest() { return g_games_reload.exchange(false); }

bool FilterMenuOpen() {
  if (g_filter.open && rex::kernel::xam::GetAvatarCatalogSearchScope() < 0) {
    g_filter = {}; PushFilterMenu();
  }
  return g_filter.open;
}

bool FilterMenuType(char ch) {
  if (!g_filter.open || !g_filter.picker) return false;
  if (ch == '\b') { if (!g_filter.query.empty()) g_filter.query.pop_back(); }
  else if (ch >= 0x20 && ch < 0x7f && g_filter.query.size() < 64) g_filter.query.push_back(ch);
  else return false;
  g_filter.choice = 0; PushFilterMenu(); return true;
}

bool HandleFilterPad(uint16_t key, uint16_t flags) {
  using rex::ui::VirtualKey;
  FilterMenuOpen();  // Close stale UI before interpreting held keys.
  const bool down = (flags & 1) != 0;
  if (key == uint16_t(VirtualKey::kXInputPadY)) {
    if (!down && g_filter_y_held) { g_filter_y_held = false; return true; }
    if (down && g_filter_y_held) return true;
    if (down && (g_filter.open || rex::kernel::xam::GetAvatarCatalogSearchScope() >= 0))
      g_filter_y_held = true;
  }
  if (g_filter.open && rex::kernel::xam::GetAvatarCatalogSearchScope() < 0) {
    g_filter = {}; PushFilterMenu(); return false;
  }
  if (!g_filter.open) {
    if (!down || key != uint16_t(VirtualKey::kXInputPadY) ||
        rex::kernel::xam::GetAvatarCatalogSearchScope() < 0) return false;
    g_filter = {}; g_filter.open = true; PushFilterMenu(); return true;
  }
  if (!down) return true;
  if (key == uint16_t(VirtualKey::kXInputPadY) ||
      (key == uint16_t(VirtualKey::kXInputPadB) && !g_filter.picker)) {
    g_filter.open = false; g_filter.picker = false; PushFilterMenu(); return true;
  }
  if (g_filter.picker) {
    auto visible = VisibleFilterChoices();
    if (key == uint16_t(VirtualKey::kXInputPadA)) {
      ApplyFilterChoice(); g_filter.picker = false; g_filter.query.clear();
    } else if (key == uint16_t(VirtualKey::kXInputPadX)) {
      g_filter.query.clear(); g_filter.choice = 0;
    } else if (key == uint16_t(VirtualKey::kXInputPadB)) {
      g_filter.picker = false; g_filter.query.clear();
    } else if (!visible.empty() && key == uint16_t(VirtualKey::kXInputPadDpadUp)) {
      g_filter.choice = (g_filter.choice + visible.size() - 1) % visible.size();
    } else if (!visible.empty() && key == uint16_t(VirtualKey::kXInputPadDpadDown)) {
      g_filter.choice = (g_filter.choice + 1) % visible.size();
    } else if (!visible.empty() && (key == uint16_t(VirtualKey::kXInputPadLShoulder) ||
                                    key == uint16_t(VirtualKey::kXInputPadRShoulder))) {
      const int direction = key == uint16_t(VirtualKey::kXInputPadRShoulder) ? 1 : -1;
      char letter = visible[g_filter.choice].label.empty() ? 'a' :
          char(std::tolower(uint8_t(visible[g_filter.choice].label.front())));
      for (int step = 0; step < 26; ++step) {
        letter = char('a' + (letter - 'a' + (direction > 0 ? 1 : 25)) % 26);
        auto found = std::find_if(visible.begin(), visible.end(), [&](const auto& value) {
          return !value.label.empty() && std::tolower(uint8_t(value.label.front())) == letter;
        });
        if (found != visible.end()) { g_filter.choice = size_t(found - visible.begin()); break; }
      }
    }
    PushFilterMenu(); return true;
  }
  if (key == uint16_t(VirtualKey::kXInputPadDpadLeft))
    g_filter.field = (g_filter.field + kFilterNames.size() - 1) % kFilterNames.size();
  else if (key == uint16_t(VirtualKey::kXInputPadDpadRight))
    g_filter.field = (g_filter.field + 1) % kFilterNames.size();
  else if (key == uint16_t(VirtualKey::kXInputPadA)) {
    LoadFilterChoices(); g_filter.picker = true;
  } else if (key == uint16_t(VirtualKey::kXInputPadX)) {
    rex::kernel::xam::SetAvatarCatalogFilter({}); RequestCatalogRebuild();
  }
  PushFilterMenu(); return true;
}

Controller& Get() {
  static Controller controller;
  return controller;
}

void Controller::Attach(rex::ui::Window* window) {
  window_ = window;
  if (window_) {
    window_->AddInputListener(this, kTopmost);
  }
}

void Controller::Detach() {
  if (window_) {
    if (open_) {
      window_->SetTextInputActive(false);
    }
    window_->RemoveInputListener(this);
    window_ = nullptr;
  }
  open_ = false;
}

// The heading line: query and match count, then a few names for the strip.
void Controller::Push() {
  std::vector<std::string> lines;
  // The game list lives on the server, so there is no local match list.
  if (!query_.empty() && store_mode_) {
    // The server counts store matches; nothing to show until it has answered.
    const int total = rex::kernel::xam::MarketplaceFilterMatches();
    if (applied_ && total >= 0) {
      char head[64];
      std::snprintf(head, sizeof(head), "%d match%s", total, total == 1 ? "" : "es");
      lines.emplace_back(head);
    }
  } else if (!query_.empty()) {
    std::vector<rex::kernel::xam::AvatarCatalogMatch> matches;
    const uint32_t total = rex::kernel::xam::QueryAvatarCatalog(query_, 8, matches);
    char head[64];
    std::snprintf(head, sizeof(head), "%u match%s", total, total == 1 ? "" : "es");
    lines.emplace_back(head);
    for (auto& m : matches) {
      lines.emplace_back(m.from_closet ? m.name + "  (closet)" : m.name);
    }
    if (total > matches.size()) {
      lines.emplace_back("...");
    }
  }
  std::vector<const char*> line_ptrs;
  line_ptrs.reserve(lines.size());
  for (const auto& s : lines) line_ptrs.push_back(s.c_str());
  SetSearchOverlay(open_, query_.c_str(), line_ptrs.data(), int(line_ptrs.size()));
}

void Controller::Toggle() {
  // A catalog grid or a store page can be searched; elsewhere the key does
  // nothing. A store page filters on the server, a grid in the local catalog.
  if (!open_) {
    const StorePage page = CurrentStorePage();
    const bool items = rex::kernel::xam::GetAvatarCatalogSearchScope() >= 0;
    if (!items && page == StorePage::kNone) {
      return;
    }
    store_mode_ = page != StorePage::kNone;
    games_list_ = page == StorePage::kGamesList;
  }
  open_ = !open_;
  // The title tick clears an applied filter when the user leaves the page it
  // was applied in; pick that up here.
  const bool live =
      store_mode_ ? !(games_list_ ? rex::kernel::xam::MarketplaceGamesFilter()
                                  : rex::kernel::xam::MarketplaceItemFilter()).empty()
                  : !rex::kernel::xam::GetAvatarCatalogSearch().empty();
  if (applied_ && !live) {
    applied_ = false;
  }
  // A fresh box, unless a filter is live: then it opens prefilled for editing.
  if (open_ && !applied_) {
    query_.clear();
  }
  if (window_) {
    window_->SetTextInputActive(open_);
  }
  Push();
}

// Enter arms the filter and asks the tick for the rebuild that re-populates
// the page. An empty query, or Esc, clears.
void Controller::Apply(bool clear) {
  if (clear) {
    query_.clear();
  }
  const bool arming = !query_.empty();
  const bool was_armed = applied_;
  applied_ = arming;
  SetSearchApplied(arming);
  if (store_mode_) {
    if (games_list_) {
      rex::kernel::xam::SetMarketplaceGamesFilter(query_);
    } else {
      rex::kernel::xam::SetMarketplaceItemFilter(query_);
    }
    if (arming || was_armed) {
      g_games_reload.store(true);
    }
  } else {
    rex::kernel::xam::SetAvatarCatalogSearch(query_);
    if (arming || was_armed) {
      RequestCatalogRebuild();
    }
  }
  open_ = false;
  if (window_) {
    window_->SetTextInputActive(false);
  }
  Push();
}

void Controller::OnKeyDown(rex::ui::KeyEvent& e) {
  using rex::ui::VirtualKey;
  if (FilterMenuOpen()) {
    switch (e.virtual_key()) {
      case VirtualKey::kBack: FilterMenuType('\b'); break;
      case VirtualKey::kEscape: HandleFilterPad(uint16_t(VirtualKey::kXInputPadB), 1); break;
      case VirtualKey::kReturn: HandleFilterPad(uint16_t(VirtualKey::kXInputPadA), 1); break;
      case VirtualKey::kDelete: HandleFilterPad(uint16_t(VirtualKey::kXInputPadX), 1); break;
      case VirtualKey::kLeft: HandleFilterPad(uint16_t(VirtualKey::kXInputPadDpadLeft), 1); break;
      case VirtualKey::kRight: HandleFilterPad(uint16_t(VirtualKey::kXInputPadDpadRight), 1); break;
      case VirtualKey::kUp: HandleFilterPad(uint16_t(VirtualKey::kXInputPadDpadUp), 1); break;
      case VirtualKey::kDown: HandleFilterPad(uint16_t(VirtualKey::kXInputPadDpadDown), 1); break;
      default: break;
    }
    e.set_handled(true);
    return;
  }
  if (!open_) {
    if (e.is_ctrl_pressed() && e.virtual_key() == VirtualKey::kF) {
      Toggle();
      e.set_handled(true);
    }
    return;
  }
  switch (e.virtual_key()) {
    case VirtualKey::kReturn:
      Apply(false);
      break;
    case VirtualKey::kEscape:
      Apply(true);
      break;
    case VirtualKey::kBack:
      if (!query_.empty()) {
        query_.pop_back();
        Push();
      }
      break;
    case VirtualKey::kF:
      // Ctrl+F while typing cancels the box and keeps a live filter.
      if (e.is_ctrl_pressed()) {
        Toggle();
      }
      break;
    default:
      break;
  }
  // Whatever it was, it was typing: nothing below gets to treat it as a pad.
  e.set_handled(true);
}

void Controller::OnKeyUp(rex::ui::KeyEvent& e) {
  if (open_ || FilterMenuOpen()) {
    e.set_handled(true);
  }
}

void Controller::OnKeyChar(rex::ui::KeyEvent& e) {
  if (FilterMenuOpen()) {
    const uint32_t ch = uint32_t(e.virtual_key());
    if (ch >= 0x20 && ch < 0x7F) FilterMenuType(char(ch));
    e.set_handled(true);
    return;
  }
  if (!open_) {
    return;
  }
  const uint32_t ch = uint32_t(e.virtual_key());  // the codepoint rides here
  if (ch >= 0x20 && ch < 0x7F && query_.size() < kMaxQuery) {
    query_.push_back(char(ch));
    Push();
  }
  e.set_handled(true);
}

}  // namespace ae_search
